create or replace function public.get_business_attribution_funnel(p_business_id uuid,p_start timestamptz default now()-interval '30 days',p_end timestamptz default now()) returns jsonb language plpgsql stable security definer set search_path='public','auth','extensions','pg_catalog' as $$ begin if auth.uid() is null then raise exception 'Authentication required'; end if; if not public.business_can_manage(p_business_id) then raise exception 'Business management access required'; end if; return (select jsonb_build_object('business_id',p_business_id,'start',p_start,'end',p_end,'qr_scans',count(*) filter(where action_type='scan'),'qr_engagements',count(*) filter(where action_type not in('scan','redeem','redemption')),'qr_redemptions',count(*) filter(where action_type in('redeem','redemption')),'attributed_users',count(distinct user_id),'campaigns',count(distinct campaign_id),'promotions',count(distinct promotion_id),'locations',count(distinct location_id)) from public.qr_attribution_events where business_id=p_business_id and created_at>=p_start and created_at<=p_end); end $$; revoke all on function public.get_business_attribution_funnel(uuid,timestamptz,timestamptz) from public,anon; grant execute on function public.get_business_attribution_funnel(uuid,timestamptz,timestamptz) to authenticated;
create or replace function public.business_growth_asset_performance(p_business_id uuid,p_start timestamptz default now()-interval '30 days',p_end timestamptz default now()) returns jsonb language plpgsql stable security definer set search_path='public','auth','extensions','pg_catalog' as $$ begin if auth.uid() is null then raise exception 'Authentication required'; end if; if not public.business_can_manage(p_business_id) then raise exception 'Business management access required'; end if; return jsonb_build_object('business_id',p_business_id,'start',p_start,'end',p_end,'promotions',coalesce((select jsonb_agg(to_jsonb(x) order by x.created_at desc) from (select p.id,p.title,p.location_id,p.active,p.created_at,count(ae.id) filter(where ae.event_type='promotion_view') views,count(ae.id) filter(where ae.event_type='promotion_redeemed') redemptions,count(distinct ae.user_id) filter(where ae.event_type='promotion_redeemed') unique_redeemers,case when count(ae.id) filter(where ae.event_type='promotion_view')=0 then 0 else round(100.0*count(ae.id) filter(where ae.event_type='promotion_redeemed')/count(ae.id) filter(where ae.event_type='promotion_view'),2) end conversion_rate_pct from public.promotions p left join public.analytics_events ae on ae.promotion_id=p.id and ae.created_at between p_start and p_end where p.business_id=p_business_id group by p.id,p.title,p.location_id,p.active,p.created_at order by p.created_at desc limit 50) x),'[]'::jsonb),'campaigns',coalesce((select jsonb_agg(to_jsonb(x) order by x.created_at desc) from (select c.id,c.name,c.campaign_type,c.goal,c.status,c.created_at,coalesce(sum(o.visits),0) visits,coalesce(sum(o.check_ins),0) check_ins,coalesce(sum(o.reviews),0) reviews,coalesce(sum(o.promotion_redemptions),0) promotion_redemptions,coalesce(sum(o.attributed_users),0) attributed_users,coalesce(sum(o.points_awarded),0) points_awarded,count(q.id) qr_attribution_events,count(distinct q.user_id) qr_attributed_users from public.enterprise_partner_campaigns c join public.enterprise_partner_networks n on n.id=c.network_id and n.owner_business_id=p_business_id left join public.enterprise_partner_campaign_outcomes o on o.campaign_id=c.id and o.metric_date between p_start::date and p_end::date left join public.qr_attribution_events q on q.campaign_id=c.id and q.business_id=p_business_id and q.created_at between p_start and p_end group by c.id,c.name,c.campaign_type,c.goal,c.status,c.created_at order by c.created_at desc limit 50) x),'[]'::jsonb)); end $$; revoke all on function public.business_growth_asset_performance(uuid,timestamptz,timestamptz) from public,anon; grant execute on function public.business_growth_asset_performance(uuid,timestamptz,timestamptz) to authenticated;
